import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def rob(arr):
    p2 = p1 = 0
    for x in arr:
        p2, p1 = p1, max(p1, p2 + x)
    return p1
if n == 1:
    print(a[0])
else:
    print(max(rob(a[:-1]), rob(a[1:])))

